    internal InnerHyperParameterTuningJobBestObjectiveNotImprovingFactory BestObjectiveNotImprovingFactory { get; set; }

    internal InnerHyperParameterTuningJobConvergenceDetectedFactory ConvergenceDetectedFactory { get; set; }

    protected override Humidifier.SageMaker.HyperParameterTuningJobTypes.TuningJobCompletionCriteria Create()
    {
        var tuningJobCompletionCriteriaResult = CreateTuningJobCompletionCriteria();
        factoryAction?.Invoke(tuningJobCompletionCriteriaResult);

        return tuningJobCompletionCriteriaResult;
    }

    private Humidifier.SageMaker.HyperParameterTuningJobTypes.TuningJobCompletionCriteria CreateTuningJobCompletionCriteria()
    {
        var tuningJobCompletionCriteriaResult = new Humidifier.SageMaker.HyperParameterTuningJobTypes.TuningJobCompletionCriteria();

        return tuningJobCompletionCriteriaResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.HyperParameterTuningJobTypes.TuningJobCompletionCriteria result)
    {
        base.CreateChildren(result);

        result.BestObjectiveNotImproving ??= BestObjectiveNotImprovingFactory?.Build();
        result.ConvergenceDetected ??= ConvergenceDetectedFactory?.Build();
    }

} // End Of Class

